//go:build integration

package integration

import (
	"encoding/json"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/trailers"
	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
)

// TestAttribution_PhantomUserLines_DirtyWorktreeAfterCondensation reproduces Bug B:
// phantom user lines appearing when a previous session's uncommitted agent changes
// persist in the worktree after condensation deletes the shadow branch.
//
// Scenario:
//  1. Session A: agent modifies main.go (+10 lines) and utils.go (+5 lines)
//  2. User commits ONLY main.go → PostCommit condenses, shadow branch deleted
//  3. utils.go remains dirty in worktree (agent wrote it, user didn't commit it)
//  4. Session A continues: next prompt fires calculatePromptAttributionAtStart
//     - No shadow branch exists (deleted after condensation)
//     - Reference falls back to baseTree (HEAD, which doesn't have utils.go changes)
//     - diffLines(baseTree_utils, worktree_utils) → 5 "user" lines (PHANTOM)
//  5. Agent makes more changes, user commits everything
//  6. Attribution shows human_added > 0 on a 100% agent commit
//
// Expected (after fix): human_added = 0 (all work was agent)
// Actual (bug): human_added = 5 (dirty worktree misattributed as user)
func TestAttribution_PhantomUserLines_DirtyWorktreeAfterCondensation(t *testing.T) {
	t.Parallel()
	env := NewTestEnv(t)
	defer env.Cleanup()

	env.InitRepo()

	// Create initial commit with two files
	env.WriteFile("main.go", "package main\n")
	env.WriteFile("utils.go", "package main\n")
	env.GitAdd("main.go")
	env.GitAdd("utils.go")
	env.GitCommit("Initial commit")

	env.InitEntire()

	// ========================================
	// TURN 1: Agent modifies both files
	// ========================================
	t.Log("Turn 1: Agent modifies main.go and utils.go")

	session := env.NewSession()
	if err := env.SimulateUserPromptSubmit(session.ID); err != nil {
		t.Fatalf("SimulateUserPromptSubmit (turn 1) failed: %v", err)
	}

	// Agent adds 10 lines to main.go
	mainContent := "package main\n\nfunc f1() { return 1 }\nfunc f2() { return 2 }\nfunc f3() { return 3 }\nfunc f4() { return 4 }\nfunc f5() { return 5 }\nfunc f6() { return 6 }\nfunc f7() { return 7 }\nfunc f8() { return 8 }\nfunc f9() { return 9 }\nfunc f10() { return 10 }\n"
	env.WriteFile("main.go", mainContent)

	// Agent adds 5 lines to utils.go
	utilsContent := "package main\n\nfunc u1() { return 1 }\nfunc u2() { return 2 }\nfunc u3() { return 3 }\nfunc u4() { return 4 }\nfunc u5() { return 5 }\n"
	env.WriteFile("utils.go", utilsContent)

	session.CreateTranscript(
		"Add functions to main.go and utils.go",
		[]FileChange{
			{Path: "main.go", Content: mainContent},
			{Path: "utils.go", Content: utilsContent},
		},
	)
	if err := env.SimulateStop(session.ID, session.TranscriptPath); err != nil {
		t.Fatalf("SimulateStop (turn 1) failed: %v", err)
	}

	// ========================================
	// USER COMMITS ONLY main.go (not utils.go)
	// This triggers condensation and shadow branch deletion.
	// utils.go remains dirty in the worktree.
	// ========================================
	t.Log("User commits only main.go (utils.go stays dirty)")

	// Only stage and commit main.go
	env.GitCommitWithShadowHooks("Add main functions", "main.go")

	firstHead := env.GetHeadHash()
	t.Logf("First commit: %s", firstHead[:7])

	// Verify utils.go is still dirty in worktree
	repo, err := git.PlainOpen(env.RepoDir)
	if err != nil {
		t.Fatalf("failed to open repo: %v", err)
	}
	wt, err := repo.Worktree()
	if err != nil {
		t.Fatalf("failed to get worktree: %v", err)
	}
	status, err := wt.Status()
	if err != nil {
		t.Fatalf("failed to get status: %v", err)
	}
	utilsStatus := status.File("utils.go")
	if utilsStatus.Worktree == 'M' || utilsStatus.Worktree == '?' {
		t.Logf("Confirmed: utils.go is dirty in worktree (status: %c)", utilsStatus.Worktree)
	} else {
		t.Logf("WARNING: utils.go worktree status: %c, staging: %c", utilsStatus.Worktree, utilsStatus.Staging)
	}

	// ========================================
	// TURN 2: New prompt in same session
	// This is where the bug occurs: calculatePromptAttributionAtStart
	// will find no shadow branch (deleted after condensation) and fall
	// back to baseTree. utils.go differs from baseTree → phantom user lines.
	// ========================================
	t.Log("Turn 2: New prompt (bug: utils.go changes attributed as user lines)")

	if err := env.SimulateUserPromptSubmit(session.ID); err != nil {
		t.Fatalf("SimulateUserPromptSubmit (turn 2) failed: %v", err)
	}

	// Agent adds a few more lines to main.go (purely agent work, no user edits)
	mainContent2 := mainContent + "\nfunc f11() { return 11 }\nfunc f12() { return 12 }\n"
	env.WriteFile("main.go", mainContent2)

	session.CreateTranscript(
		"Add more functions",
		[]FileChange{
			{Path: "main.go", Content: mainContent2},
			{Path: "utils.go", Content: utilsContent},
		},
	)
	if err := env.SimulateStop(session.ID, session.TranscriptPath); err != nil {
		t.Fatalf("SimulateStop (turn 2) failed: %v", err)
	}

	// ========================================
	// USER COMMITS EVERYTHING
	// ========================================
	t.Log("User commits both files")

	env.GitCommitWithShadowHooks("Add more functions and utils", "main.go", "utils.go")

	// ========================================
	// VERIFY ATTRIBUTION
	// ========================================
	headHash := env.GetHeadHash()
	t.Logf("Second commit: %s", headHash[:7])

	commitObj, err := repo.CommitObject(plumbing.NewHash(headHash))
	if err != nil {
		t.Fatalf("failed to get commit object: %v", err)
	}

	checkpointID, found := trailers.ParseCheckpoint(commitObj.Message)
	if !found {
		t.Fatal("Second commit should have Entire-Checkpoint trailer")
	}

	sessionsRef, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
	if err != nil {
		t.Fatalf("Failed to get entire/checkpoints/v1 branch: %v", err)
	}

	sessionsCommit, err := repo.CommitObject(sessionsRef.Hash())
	if err != nil {
		t.Fatalf("Failed to get sessions commit: %v", err)
	}

	sessionsTree, err := sessionsCommit.Tree()
	if err != nil {
		t.Fatalf("Failed to get sessions tree: %v", err)
	}

	metadataPath := SessionMetadataPath(checkpointID.String())
	metadataFile, err := sessionsTree.File(metadataPath)
	if err != nil {
		t.Fatalf("Failed to read session metadata.json at path %s: %v", metadataPath, err)
	}

	metadataContent, err := metadataFile.Contents()
	if err != nil {
		t.Fatalf("Failed to read metadata content: %v", err)
	}

	var metadata checkpoint.CommittedMetadata
	if err := json.Unmarshal([]byte(metadataContent), &metadata); err != nil {
		t.Fatalf("Failed to parse metadata.json: %v", err)
	}

	if metadata.InitialAttribution == nil {
		t.Fatal("InitialAttribution is nil")
	}

	attr := metadata.InitialAttribution
	t.Logf("Attribution: agent=%d, human_added=%d, human_modified=%d, human_removed=%d, total=%d, percentage=%.1f%%",
		attr.AgentLines, attr.HumanAdded, attr.HumanModified, attr.HumanRemoved,
		attr.TotalCommitted, attr.AgentPercentage)

	// The user made ZERO edits. All work was by the agent.
	// Bug: human_added will be > 0 because utils.go's agent changes were
	// misattributed as user additions in the PromptAttribution after condensation.
	//
	// Expected (after fix): human_added = 0, agent_percentage = 100%
	if attr.HumanAdded != 0 {
		t.Errorf("BUG CONFIRMED: HumanAdded = %d, want 0 — agent changes to utils.go were misattributed as user additions after shadow branch deletion",
			attr.HumanAdded)
	}

	if attr.AgentPercentage < 99.9 {
		t.Errorf("BUG CONFIRMED: AgentPercentage = %.1f%%, want 100%% — phantom user lines deflating agent credit",
			attr.AgentPercentage)
	}
}

//go:build integration

package integration

import (
	"encoding/json"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/trailers"
	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
)

// TestAttribution_PhantomUserLines_CarryForwardSameSession tests that
// carry-forward correctly prevents phantom user lines when the same session
// continues after a partial commit.
//
// Result: PASSES — carry-forward creates a new shadow branch with uncommitted
// agent changes, so the next PromptAttribution correctly uses it as reference.
func TestAttribution_PhantomUserLines_CarryForwardSameSession(t *testing.T) {
	t.Parallel()
	env := NewTestEnv(t)
	defer env.Cleanup()

	env.InitRepo()

	env.WriteFile("main.go", "package main\n")
	env.WriteFile("utils.go", "package main\n")
	env.GitAdd("main.go")
	env.GitAdd("utils.go")
	env.GitCommit("Initial commit")

	env.InitEntire()

	// Turn 1: Agent modifies both files
	session := env.NewSession()
	if err := env.SimulateUserPromptSubmit(session.ID); err != nil {
		t.Fatalf("SimulateUserPromptSubmit (turn 1) failed: %v", err)
	}

	mainContent := "package main\n\nfunc f1() { return 1 }\nfunc f2() { return 2 }\nfunc f3() { return 3 }\n"
	utilsContent := "package main\n\nfunc u1() { return 1 }\nfunc u2() { return 2 }\nfunc u3() { return 3 }\n"
	env.WriteFile("main.go", mainContent)
	env.WriteFile("utils.go", utilsContent)

	session.CreateTranscript(
		"Add functions",
		[]FileChange{
			{Path: "main.go", Content: mainContent},
			{Path: "utils.go", Content: utilsContent},
		},
	)
	if err := env.SimulateStop(session.ID, session.TranscriptPath); err != nil {
		t.Fatalf("SimulateStop (turn 1) failed: %v", err)
	}

	// User commits ONLY main.go
	env.GitCommitWithShadowHooks("Add main functions", "main.go")

	// Turn 2: Same session continues
	if err := env.SimulateUserPromptSubmit(session.ID); err != nil {
		t.Fatalf("SimulateUserPromptSubmit (turn 2) failed: %v", err)
	}

	mainContent2 := mainContent + "\nfunc f4() { return 4 }\n"
	env.WriteFile("main.go", mainContent2)

	session.CreateTranscript(
		"Add f4",
		[]FileChange{
			{Path: "main.go", Content: mainContent2},
			{Path: "utils.go", Content: utilsContent},
		},
	)
	if err := env.SimulateStop(session.ID, session.TranscriptPath); err != nil {
		t.Fatalf("SimulateStop (turn 2) failed: %v", err)
	}

	env.GitCommitWithShadowHooks("Add f4 and utils", "main.go", "utils.go")

	// Verify attribution
	attr := getAttributionForHead(t, env)
	t.Logf("Attribution: agent=%d, human_added=%d, total=%d, percentage=%.1f%%",
		attr.AgentLines, attr.HumanAdded, attr.TotalCommitted, attr.AgentPercentage)

	if attr.HumanAdded != 0 {
		t.Errorf("HumanAdded = %d, want 0 — all work was agent", attr.HumanAdded)
	}
	if attr.AgentPercentage < 99.9 {
		t.Errorf("AgentPercentage = %.1f%%, want 100%%", attr.AgentPercentage)
	}
}

// TestAttribution_PhantomUserLines_NewSessionDirtyWorktree tests whether a
// brand new session starting with a dirty worktree (from a previous agent
// session) produces phantom user lines.
//
// Scenario:
//  1. Session A: agent modifies utils.go, user commits everything, session ends
//  2. Agent also left helper.go dirty (not committed, not in session A's filesTouched)
//     Simulated by writing helper.go AFTER the commit
//  3. Session B starts (completely new session) with dirty helper.go in worktree
//  4. First PromptAttribution in Session B: diffs baseTree → worktree
//     helper.go differs from baseTree → counted as "user additions"
//  5. Agent works on main.go, user commits everything
//  6. Check: does attribution show phantom human_added?
func TestAttribution_PhantomUserLines_NewSessionDirtyWorktree(t *testing.T) {
	t.Parallel()
	env := NewTestEnv(t)
	defer env.Cleanup()

	env.InitRepo()

	env.WriteFile("main.go", "package main\n")
	env.WriteFile("helper.go", "package main\n")
	env.GitAdd("main.go")
	env.GitAdd("helper.go")
	env.GitCommit("Initial commit")

	env.InitEntire()

	// ========================================
	// Session A: agent works, user commits, session ends
	// ========================================
	sessionA := env.NewSession()
	if err := env.SimulateUserPromptSubmit(sessionA.ID); err != nil {
		t.Fatalf("Session A: SimulateUserPromptSubmit failed: %v", err)
	}

	mainContent := "package main\n\nfunc f1() { return 1 }\n"
	env.WriteFile("main.go", mainContent)

	sessionA.CreateTranscript(
		"Add f1",
		[]FileChange{{Path: "main.go", Content: mainContent}},
	)
	if err := env.SimulateStop(sessionA.ID, sessionA.TranscriptPath); err != nil {
		t.Fatalf("Session A: SimulateStop failed: %v", err)
	}

	env.GitCommitWithShadowHooks("Session A commit", "main.go")

	if err := env.SimulateSessionEnd(sessionA.ID); err != nil {
		t.Fatalf("Session A: SimulateSessionEnd failed: %v", err)
	}

	// ========================================
	// Simulate dirty worktree: some tool/previous agent left helper.go modified
	// (After Session A committed and ended, something changed helper.go)
	// ========================================
	dirtyHelperContent := "package main\n\nfunc h1() { return 1 }\nfunc h2() { return 2 }\nfunc h3() { return 3 }\nfunc h4() { return 4 }\nfunc h5() { return 5 }\n"
	env.WriteFile("helper.go", dirtyHelperContent)
	t.Log("Dirty worktree: helper.go has 5 new lines (not from this session)")

	// ========================================
	// Session B: new session starts with dirty worktree
	// ========================================
	sessionB := env.NewSession()
	if err := env.SimulateUserPromptSubmit(sessionB.ID); err != nil {
		t.Fatalf("Session B: SimulateUserPromptSubmit failed: %v", err)
	}

	// Agent adds more functions to main.go (all agent work)
	mainContent2 := mainContent + "\nfunc f2() { return 2 }\nfunc f3() { return 3 }\n"
	env.WriteFile("main.go", mainContent2)

	sessionB.CreateTranscript(
		"Add f2 and f3",
		[]FileChange{{Path: "main.go", Content: mainContent2}},
	)
	if err := env.SimulateStop(sessionB.ID, sessionB.TranscriptPath); err != nil {
		t.Fatalf("Session B: SimulateStop failed: %v", err)
	}

	// User commits both files
	env.GitCommitWithShadowHooks("Session B commit", "main.go", "helper.go")

	// ========================================
	// VERIFY ATTRIBUTION
	// ========================================
	attr := getAttributionForHead(t, env)
	t.Logf("Attribution: agent=%d, human_added=%d, human_modified=%d, total=%d, percentage=%.1f%%",
		attr.AgentLines, attr.HumanAdded, attr.HumanModified, attr.TotalCommitted, attr.AgentPercentage)

	// helper.go's 5 lines were NOT written by the user in this session.
	// They were already in the worktree when Session B started.
	// The agent in Session B only touched main.go.
	//
	// Expected: helper.go lines are correctly counted as non-agent additions (human_added)
	// because from Session B's perspective, helper.go is a non-agent file that changed
	// between base and HEAD. The system can't know who wrote those lines.
	//
	// This test documents the current behavior. If human_added > 0, it shows that
	// pre-session worktree dirt gets attributed as human additions.
	t.Logf("NOTE: human_added=%d includes pre-session worktree dirt from helper.go", attr.HumanAdded)
	t.Logf("This is the expected behavior for non-agent files — the system correctly")
	t.Logf("identifies them as 'not written by this session's agent'.")

	// The question is: IS this the mechanism behind the 69% checkpoint?
	// For that case, the phantom lines were on AGENT-TOUCHED files, not separate files.
}

// TestAttribution_PhantomUserLines_CheckpointGap tests whether agent changes
// between SaveStep and the next prompt cause phantom user lines.
//
// Scenario: The agent's transcript reports modifying file A, but the agent also
// modified file B via a Bash command (not tracked in ModifiedFiles). SaveStep
// captures A but not B. The next PromptAttribution sees B as dirty against the
// shadow tree (which doesn't have B's changes) → "user addition."
func TestAttribution_PhantomUserLines_CheckpointGap(t *testing.T) {
	t.Parallel()
	env := NewTestEnv(t)
	defer env.Cleanup()

	env.InitRepo()

	env.WriteFile("main.go", "package main\n")
	env.WriteFile("generated.go", "package main\n// generated\n")
	env.GitAdd("main.go")
	env.GitAdd("generated.go")
	env.GitCommit("Initial commit")

	env.InitEntire()

	// ========================================
	// Turn 1: Agent modifies main.go (tracked) AND generated.go (NOT tracked in SaveStep)
	// ========================================
	session := env.NewSession()
	if err := env.SimulateUserPromptSubmit(session.ID); err != nil {
		t.Fatalf("SimulateUserPromptSubmit (turn 1) failed: %v", err)
	}

	mainContent := "package main\n\nfunc f1() { return 1 }\nfunc f2() { return 2 }\n"
	env.WriteFile("main.go", mainContent)

	// Agent also modified generated.go (e.g., via bash command, code generation)
	// but this is NOT reported in the transcript's file changes
	generatedContent := "package main\n// generated\nfunc gen1() { return 1 }\nfunc gen2() { return 2 }\nfunc gen3() { return 3 }\n"
	env.WriteFile("generated.go", generatedContent)

	// SaveStep only knows about main.go — generated.go is NOT in the checkpoint
	session.CreateTranscript(
		"Add functions",
		[]FileChange{
			{Path: "main.go", Content: mainContent},
			// generated.go intentionally OMITTED — simulating a checkpoint gap
		},
	)
	if err := env.SimulateStop(session.ID, session.TranscriptPath); err != nil {
		t.Fatalf("SimulateStop (turn 1) failed: %v", err)
	}

	// ========================================
	// Turn 2: New prompt — generated.go is dirty but not in shadow tree
	// calculatePromptAttributionAtStart should see generated.go as changed
	// since shadow tree doesn't have the agent's modifications
	// ========================================
	t.Log("Turn 2: generated.go is dirty but not in shadow tree (checkpoint gap)")

	if err := env.SimulateUserPromptSubmit(session.ID); err != nil {
		t.Fatalf("SimulateUserPromptSubmit (turn 2) failed: %v", err)
	}

	// Agent adds one more line to main.go
	mainContent2 := mainContent + "\nfunc f3() { return 3 }\n"
	env.WriteFile("main.go", mainContent2)

	session.CreateTranscript(
		"Add f3",
		[]FileChange{
			{Path: "main.go", Content: mainContent2},
			{Path: "generated.go", Content: generatedContent},
		},
	)
	if err := env.SimulateStop(session.ID, session.TranscriptPath); err != nil {
		t.Fatalf("SimulateStop (turn 2) failed: %v", err)
	}

	// User commits everything
	env.GitCommitWithShadowHooks("Add all functions", "main.go", "generated.go")

	// ========================================
	// VERIFY ATTRIBUTION
	// ========================================
	attr := getAttributionForHead(t, env)
	t.Logf("Attribution: agent=%d, human_added=%d, human_modified=%d, total=%d, percentage=%.1f%%",
		attr.AgentLines, attr.HumanAdded, attr.HumanModified, attr.TotalCommitted, attr.AgentPercentage)

	// Bug: generated.go's 3 agent-added lines were NOT in the shadow tree after turn 1.
	// At turn 2's PromptAttribution, diff(shadow, worktree) for generated.go shows
	// 3 "user additions" — but they're actually agent work from turn 1.
	//
	// Expected (after fix): human_added = 0
	// Actual (bug): human_added = 3 (generated.go misattributed)
	if attr.HumanAdded != 0 {
		t.Errorf("BUG CONFIRMED: HumanAdded = %d, want 0 — generated.go agent changes misattributed as user additions due to checkpoint gap",
			attr.HumanAdded)
	}

	if attr.AgentPercentage < 99.9 {
		t.Errorf("BUG CONFIRMED: AgentPercentage = %.1f%%, want 100%%", attr.AgentPercentage)
	}
}

// getAttributionForHead reads attribution from the most recent commit's checkpoint.
func getAttributionForHead(t *testing.T, env *TestEnv) *checkpoint.InitialAttribution {
	t.Helper()

	headHash := env.GetHeadHash()
	repo, err := git.PlainOpen(env.RepoDir)
	if err != nil {
		t.Fatalf("failed to open repo: %v", err)
	}

	commitObj, err := repo.CommitObject(plumbing.NewHash(headHash))
	if err != nil {
		t.Fatalf("failed to get commit object: %v", err)
	}

	checkpointID, found := trailers.ParseCheckpoint(commitObj.Message)
	if !found {
		t.Fatalf("Commit %s should have Entire-Checkpoint trailer", headHash[:7])
	}

	sessionsRef, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
	if err != nil {
		t.Fatalf("Failed to get entire/checkpoints/v1 branch: %v", err)
	}

	sessionsCommit, err := repo.CommitObject(sessionsRef.Hash())
	if err != nil {
		t.Fatalf("Failed to get sessions commit: %v", err)
	}

	sessionsTree, err := sessionsCommit.Tree()
	if err != nil {
		t.Fatalf("Failed to get sessions tree: %v", err)
	}

	metadataPath := SessionMetadataPath(checkpointID.String())
	metadataFile, err := sessionsTree.File(metadataPath)
	if err != nil {
		t.Fatalf("Failed to read session metadata.json at path %s: %v", metadataPath, err)
	}

	metadataContent, err := metadataFile.Contents()
	if err != nil {
		t.Fatalf("Failed to read metadata content: %v", err)
	}

	var metadata checkpoint.CommittedMetadata
	if err := json.Unmarshal([]byte(metadataContent), &metadata); err != nil {
		t.Fatalf("Failed to parse metadata.json: %v", err)
	}

	if metadata.InitialAttribution == nil {
		t.Fatal("InitialAttribution is nil")
	}

	return metadata.InitialAttribution
}

